from pathlib import Path
import json
O=Path(__file__).resolve().parent;ROOT=O.parents[4]
p=O/'write_interactions.py';t=p.read_text();a=t.index('summary=');b=t.index("for part in ['a','b']:",a)
summary=[('Le syndrome observé, la cause et la temporalité se prouvent séparément ; N05 n’est pas toute créatinine élevée.','CH-CIM'),('Aucun taux directN05 retenu ; les chiffresMRC/IRA ne mesurent pas ce cadre sans précision.','CH-SGN-DEF'),('Perméabilité, filtration, rétention et lésions expliquent des signes complémentaires ; une image ne nomme pas toute la cause.','EU-HISTO'),('Sécuriser, dater, localiser et expliquer ; les investigations ne retardent pas les soins d’une complication.','EU-IRA'),('Résultats datés, médicaments réels, famille, infection et signes systémiques orientent l’enquête.','EU-SYNDROMES'),('Volume, pression, respiration et tolérance sont évalués avant de choisir une stratégie.','EU-IRA'),('Aigu, rapidement progressif, chronique, IRA, MRC et morphologie décrivent des axes différents.','EU-SYNDROMES'),('Confirmer les signes, décrire la fonction dans le temps, chercher cause et documenter les incertitudes.','INT-AKI'),('Chaque examen répond à une question ; tissu et immunologie sont urgents si progression rapide suspectée.','INT-GN-GENERAL'),('La discordance entre hypothèse et données impose de rouvrir le diagnostic.','EU-IRA'),('Traiter les complications puis choisir traitement de cause et éventuelle néphroprotection selon preuves et FI.','FI-LASIX-IV'),('Le suivi réduit les incertitudes, vérifie la récupération et recherche des séquelles sans perdre le patient.','INT-CKD-RISK'),('Une synthèse clinique donne syndrome, gravité, hypothèses et plan ; exercicesMEDINA nonofficiels.','CH-PROFILES'),('Le degré de précision du libellé ne mesure pas la gravité et ne prescrit pas de traitement universel.','CH-CIM')]
t=t[:a]+'summary='+repr(summary)+'\n'+t[b:]
a=t.index('cases=');b=t.index('for i,(title,body,refs)',a)
cases=[('Information manquante, urgence présente','<p>Une personne sans résultat antérieur présente une hématurie, une créatinine élevée, une oligurie et une dyspnée. La durée est inconnue ; l’absence de preuve de chronicité ne rassure pas. Évaluer immédiatement volume, respiration, pression, potassium/ECG et équilibre acido-basique, puis organiser les soins hospitaliers selon gravité.</p><p>Retrouver les valeurs antérieures et préciser la cause en parallèle. Attendre trois mois pour nommer laMRC exposerait à retarder le traitement d’une complication actuelle.</p>',('EU-IRA','INT-AKI','INT-CKD-DEF')),('Une urine rouge ne donne pas le compartiment','<p>La bandelette est positive pour le sang. La microscopie, le recueil et le contexte sont nécessaires avant d’affirmer une hématurie glomérulaire. Acanthocytes ou cylindres hématiques soutiennent la localisation ; un résultat négatif ne suffit pas à l’exclure.</p><p>Quantifier albumine et protéines, apprécier fonction et retentissement, rechercher des alternatives selon les symptômes. Une hématurie ne remplace pas le bilan d’une obstruction ni d’un risque urologique.</p>',('CH-HUG-DEF','CH-HUG-URO','EU-HEMAT')),('Le croissant ne nomme pas toute la maladie','<p>Une biopsie décrit une prolifération extracapillaire. Des mécanismes pauci-immuns, immuns ou anti-membrane basale peuvent produire ce type de lésion. Optique, immunofluorescence, immunologie et clinique se confrontent ; la colorationPAS seule ne montre pas un dépôt linéaireIgG.</p><p>La trajectoire fonctionnelle et le retentissement déterminent aussi l’urgence. Le seul motN05 ou une image ne justifie pas le même protocole immunosuppresseur pour tous.</p>',('EU-IRA','EU-HISTO','INT-GN-GENERAL')),('Distinguer dose, voie et indication','<p>Un œdème pulmonaire aigu ne se traite pas en recopiant un schéma d’entretien deLasix40mg oral. LaFI de l’ampoule20mg, mars2025, donne un schémaIV spécifique et une vitesse maximale d’injection ; les autres mesures et l’éventuelle épuration se discutent en urgence.</p><p>Une augmentation des urines n’établit pas la récupération rénale. Surveiller retentissement, électrolytes et fonction ; respecter contre-indications et risque de déplétion.</p>',('FI-LASIX-IV','FI-LASIX-PO','INT-AKI'))]
t=t[:a]+'cases='+repr(cases)+'\n'+t[b:]
a=t.index('quiz=');b=t.index("p=CH/'N05_b.html'",a)
quiz=[('Sans résultat ancien, une créatinine élevée prouve-t-elle une atteinte aiguë ?','Non, la durée reste à documenter.','Oui, toute première découverte est aiguë.','Retrouver les valeurs antérieures et suivre la trajectoire ; évaluer la gravité immédiatement.','EU-IRA'),('Une baisse68→51 correspond à quelle variation ?','Une baisse de25%.','Une baisse de17%.','(68−51)÷68×100=25%. En suiviMRC ce repère appelle une évaluation, sans prouver une perte irréversible.','INT-CKD-RISK'),('Un croissantPAS prouve-t-il une maladieanti-MBG ?','Non, plusieurs mécanismes sont possibles.','Oui, lePAS suffit.','L’immunofluorescence, les anticorps et la clinique complètent la lésion morphologique.','EU-HISTO'),('Faut-il attendre une cause certaine pour traiter une complication menaçante ?','Non, sécurisation et diagnostic avancent en parallèle.','Oui, le bilan doit toujours être terminé.','Troubles hydriques, électrolytiques ou acido-basiques menaçants peuvent imposer une épuration urgente.','INT-AKI')]
t=t[:a]+'quiz='+repr(quiz)+'\n'+t[b:];p.write_text(t)
# Suffixes remain after the clinical conclusion, in the reserved chapter only.
labels=['Anomalies glomérulaires mineures','Lésions glomérulaires segmentaires et focales','Glomérulonéphrite membraneuse diffuse','Glomérulonéphrite mésangio-proliférative diffuse','Glomérulonéphrite proliférative endocapillaire diffuse','Glomérulonéphrite mésangiocapillaire diffuse','Maladie à dépôt dense','Glomérulonéphrite diffuse en croissant','Autres modifications morphologiques','Type de modification morphologique non précisé']
annex='''from lesson_helpers import *
labels=LABELS
body='<p>Le diagnostic clinique précède le codage. Les suffixes morphologiquesOFS ci-dessous ne sont ni dix stades ni dix traitements. Les formes .0 à .8 nécessitent normalement une preuve précise par biopsie ou autopsie ; .9 décrit une morphologie non précisée.</p>'+table(['Sous-code','Libellé morphologique'],[['N05.'+str(i),x] for i,x in enumerate(labels)])+'<p>N05 inclut glomérulopathie, glomérulonéphrite et néphriteSAI, ainsi que maladie rénaleSAI avec morphologie précisée. Il exclut néphropathie ou maladie rénaleSAI sans lésion morphologique précisée N28.9 et néphrite tubulo-interstitielleSAI N12. Le code ne doit pas remplacer la recherche de cause et de temporalité ; la volonté de choisir un suffixe n’est pas une indication de biopsie.</p>'
p=CH/'N05_b.html';txt=p.read_text();end=txt.rfind('</div></div>');assert end>0;p.write_text(txt[:end]+sec('annexe-cim','Après la conclusion clinique : sous-codes morphologiques',body,('CH-CIM',))+txt[end:])
'''.replace('LABELS',repr(labels));(O/'add_annex.py').write_text(annex)
g=ROOT/'glossary/n05.py';g.write_text('''from cardio_1 import a, G
# N05 — définition conditionnelle, sans modifier les anciens glossaires.
if 'GNRP' not in G:
    a('GNRP', [('GN','Glomérulonéphrite'),('RP','Rapidement progressive')], 'Glomérulonéphrite rapidement progressive', '<p>Dégradation rapide de fonction avec signes glomérulaires : urgence de bilan et de décision spécialisée. La lésion en croissant et la cause se précisent par le tissu et le contexte.</p>', 'n05-exp-7')
if 'SGN' not in G:
    a('SGN', [('SGN','Schweizerische Gesellschaft für Nephrologie')], 'Société suisse de néphrologie', '<p>Référence suisse pour la maladie rénale chronique établie ; elle ne transforme pas N05 en protocole de néphroprotection automatique.</p>', 'n05-exp-11')
''')
p=ROOT/'chapters.json';j=json.loads(p.read_text());assert not any(x['code']=='N05' for x in j);j.append(dict(code='N05',title='Syndrome néphritique, sans précision',covers=['N05'],wave=4,integrated=True,added='2026-11-02'));p.write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n')
